using namespace std;
using ll = long long;

const int MOD = 1'000'000'007;

ll modpow(ll b, ll e) {
    ll ans = 1;
    for (; e; e /= 2) {
        if (e % 2 == 1) ans = (ans * b) % MOD;
        b = (b * b) % MOD;
    }
    return ans;
}

struct disjoint_set {
    vector<int> parent, rnk;
    int comps;

    disjoint_set(int n) : parent(n), rnk(n), comps(n) {
        iota(parent.begin(), parent.end(), 0);
    }

    int find(int u) {
        if (parent[u] != u) parent[u] = find(parent[u]);
        return parent[u];
    }

    void merge(int u, int v) {
        u = find(u);
        v = find(v);

        if (u == v) return;
        if (rnk[u] > rnk[v]) swap(u, v);
        parent[u] = v;
        if (rnk[u] == rnk[v]) ++rnk[v];
        --comps;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(NULL);

    ll p, k;
    cin >> p >> k;

    vector<bool> seen(p);
    disjoint_set dsu(p);

    for (ll i = 0; i < p; ++i) {
        for (ll j = i; !seen[j]; j = (j * k) % p) {
            seen[j] = true;
            dsu.merge(i, j);
        }
    }

    int c = dsu.comps;
    if (k != 1) --c;

    cout << modpow(p, c) << endl;

    return 0;
}

